#!/bin/bash
set -e
echo "🚀 Встановлюємо файли OracleX..."

echo "" | base64 -d > src/security.js
echo "✅ src/security.js"
echo "" | base64 -d > src/auth.js
echo "✅ src/auth.js"
echo "" | base64 -d > src/api.js
echo "✅ src/api.js"
echo "" | base64 -d > src/db.js
echo "✅ src/db.js"
